void func_800820D0(a0, a1, a2, a3, a4, a5, a6, a7)
u8 *a0;
u8 a1;
u8 a2;
u8 a3;
u8 a4;
u8 a5;
u8 a6;
s16 a7;
{
    f32 cr;
    f32 cg;
    f32 cb;
    f32 dr;
    f32 dg;
    f32 db;
    s16 i;

    a7 = a7 - 1;
    cr = a1;
    cg = a2;
    cb = a3;
    dr = (a4 - (f32)a1) / a7;
    dg = (a5 - (f32)a2) / a7;
    db = (a6 - (f32)a3) / a7;
    for (i = 0; i < a7; i++) {
        *a0++ = cr;
        *a0++ = cg;
        *a0++ = cb;
        cr += dr;
        cg += dg;
        cb += db;
    }
}

/* Initialises one board cell 4-point quad: maps the rotation code through the swap
 * 0<->1, 2<->3, writes an axis-aligned box into the live bank (x extents a3*16+1 and
 * a3*16+14, y extents 1 and 14), stores a3*64 (the cell pixel origin) to +0x009, then
 * cyclically rotates the four corner pairs 4 - a4 times (0->2->3->1->0), so a4 selects
 * the final orientation.
 * K&R definition: a1/a2/a3 home with sll/sra entry narrowing and a4 arrives via
 * lh 0x12($sp). Same signature family as func_800820D0.
 * Load-bearing, do not tidy: the case order 0,1,3,2 (case bodies emit in source order
 * and ROM lays them out a1=1, a1=0, a1=2, a1=3); the x-before-i declaration order; the
 * shared "x" (ROM emits sll v0,a3,4 then sll t7,v0,2, i.e. the source nests (a3*16)*4);
 * reassigning the PARAM a1 rather than naming a local (ROM keeps it in $a1, its home
 * register); all EIGHT corner temps live before any store; and the inlined "4 - a4"
 * bound -- naming it claims a register colour ahead of the induction variable and
 * rotates v0/v1 across the whole function. */
void func_800823F0(a0, a1, a2, a3, a4)
Foo84 *a0;
s16 a1;
s16 a2;
s16 a3;
s16 a4;
{
    s32 x;
    s16 i;

    switch (a1) {
    case 0:
        a1 = 1;
        break;
    case 1:
        a1 = 0;
        break;
    case 3:
        a1 = 2;
        break;
    case 2:
        a1 = 3;
        break;
    }
    x = a3 * 0x10;
    a0->f9 = x * 4;
    a0->f078[a2][a1][0][0] = x + 1;
    a0->f078[a2][a1][0][1] = 0xE;
    a0->f078[a2][a1][1][0] = x + 0xE;
    a0->f078[a2][a1][1][1] = 0xE;
    a0->f078[a2][a1][2][0] = x + 1;
    a0->f078[a2][a1][2][1] = 1;
    a0->f078[a2][a1][3][0] = x + 0xE;
    a0->f078[a2][a1][3][1] = 1;
    for (i = 0; i < 4 - a4; i++) {
        s16 x0 = a0->f078[a2][a1][0][0];
        s16 y0 = a0->f078[a2][a1][0][1];
        s16 x1 = a0->f078[a2][a1][1][0];
        s16 y1 = a0->f078[a2][a1][1][1];
        s16 x2 = a0->f078[a2][a1][2][0];
        s16 y2 = a0->f078[a2][a1][2][1];
        s16 x3 = a0->f078[a2][a1][3][0];
        s16 y3 = a0->f078[a2][a1][3][1];
        a0->f078[a2][a1][2][0] = x0;
        a0->f078[a2][a1][2][1] = y0;
        a0->f078[a2][a1][0][0] = x1;
        a0->f078[a2][a1][0][1] = y1;
        a0->f078[a2][a1][3][0] = x2;
        a0->f078[a2][a1][3][1] = y2;
        a0->f078[a2][a1][1][0] = x3;
        a0->f078[a2][a1][1][1] = y3;
    }
}

